// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GoogleLogin Signs in with Google (the ID token from Google's sign-in button).
	// (POST /v1/auth/google)
	GoogleLogin(w http.ResponseWriter, r *http.Request)
	// Logout Signs out this device, or every device. The next visit starts as a new guest.
	// (POST /v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// MergeAccounts Says yes to a merge offer; the other account moves into this one.
	// (POST /v1/auth/merge)
	MergeAccounts(w http.ResponseWriter, r *http.Request)
	// CheckTelegramLogin Collects a Telegram sign-in once the player pressed Start in the bot.
	// (POST /v1/auth/telegram/check)
	CheckTelegramLogin(w http.ResponseWriter, r *http.Request)
	// StartTelegramLogin Starts "sign in with Telegram" through the bot.
	// (POST /v1/auth/telegram/start)
	StartTelegramLogin(w http.ResponseWriter, r *http.Request)
	// TelegramWebAppLogin Signs in inside Telegram (the game opened as a Mini App), with Telegram's signed initData.
	// (POST /v1/auth/telegram/webapp)
	TelegramWebAppLogin(w http.ResponseWriter, r *http.Request)
	// GetConfig What the game needs to know before it draws the sign-in buttons and the avatar picker.
	// (GET /v1/config)
	GetConfig(w http.ResponseWriter, r *http.Request)
	// CreateGame Starts a solo game on a map.
	// (POST /v1/games)
	CreateGame(w http.ResponseWriter, r *http.Request)
	// GetGame A game with every finished round. Also used to resume after a reload.
	// (GET /v1/games/{gameId})
	GetGame(w http.ResponseWriter, r *http.Request, gameId GameId)
	// FinishGame Ends the game now, after any round (endless games end this way).
	// (POST /v1/games/{gameId}/finish)
	FinishGame(w http.ResponseWriter, r *http.Request, gameId GameId)
	// NextRound Starts the next round. The server picks the panorama.
	// (POST /v1/games/{gameId}/rounds)
	NextRound(w http.ResponseWriter, r *http.Request, gameId GameId)
	// RoundFailed The viewer could not open this panorama; the server picks another for the same round.
	// (POST /v1/games/{gameId}/rounds/{n}/fail)
	RoundFailed(w http.ResponseWriter, r *http.Request, gameId GameId, n RoundN)
	// Guess Ends the round with a guess (or none), scored by the server.
	// (POST /v1/games/{gameId}/rounds/{n}/guess)
	Guess(w http.ResponseWriter, r *http.Request, gameId GameId, n RoundN)
	// UseHint Spends one hint of this round.
	// (POST /v1/games/{gameId}/rounds/{n}/hint)
	UseHint(w http.ResponseWriter, r *http.Request, gameId GameId, n RoundN)
	// RoundShown The panorama is on screen; the round's clock starts now.
	// (POST /v1/games/{gameId}/rounds/{n}/shown)
	RoundShown(w http.ResponseWriter, r *http.Request, gameId GameId, n RoundN)
	// GetHealth The process is up.
	// (GET /v1/health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// ListMaps The maps on the menu.
	// (GET /v1/maps)
	ListMaps(w http.ResponseWriter, r *http.Request)

	// (GET /v1/maps/{slug})
	GetMap(w http.ResponseWriter, r *http.Request, slug Slug)

	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// ListMyGames The player's finished games, newest first.
	// (GET /v1/me/games)
	ListMyGames(w http.ResponseWriter, r *http.Request, params ListMyGamesParams)
	// UnlinkIdentity Removes a way to sign in. The last one stays (`last_identity`).
	// (POST /v1/me/identities/unlink)
	UnlinkIdentity(w http.ResponseWriter, r *http.Request)
	// UpdatePrefs Saves the player's preferences, so every device gets them.
	// (POST /v1/me/prefs)
	UpdatePrefs(w http.ResponseWriter, r *http.Request)

	// (GET /v1/me/profile)
	GetMyProfile(w http.ResponseWriter, r *http.Request)
	// UpdateProfile Changes the player's name or avatar.
	// (POST /v1/me/profile)
	UpdateProfile(w http.ResponseWriter, r *http.Request)
	// ListMyStreets The Tashkent streets the player has been on, learned ones marked, closest guess first.
	// (GET /v1/me/streets)
	ListMyStreets(w http.ResponseWriter, r *http.Request)
	// GetDemoPanorama The drawn test panorama of the `demo` provider (a JPEG).
	// (GET /v1/pano/demo/{ref})
	GetDemoPanorama(w http.ResponseWriter, r *http.Request, ref string)
	// GetPlace A place for the place picker, with where it is and what is inside it.
	// (GET /v1/places/{slug})
	GetPlace(w http.ResponseWriter, r *http.Request, slug Slug)
	// GetPlaceShape A place's simplified boundary as GeoJSON, for the guess map.
	// (GET /v1/places/{slug}/shape)
	GetPlaceShape(w http.ResponseWriter, r *http.Request, slug Slug)
	// GetReady The database and Valkey answer.
	// (GET /v1/ready)
	GetReady(w http.ResponseWriter, r *http.Request)
	// CreateRoom Opens a live room on a map; the caller is its host.
	// (POST /v1/rooms)
	CreateRoom(w http.ResponseWriter, r *http.Request)
	// GetRoom A room as the caller sees it (`joined` false before their page has joined it).
	// (GET /v1/rooms/{code})
	GetRoom(w http.ResponseWriter, r *http.Request, code RoomCode)
	// MakeRoomHost The host hands the room to another player.
	// (POST /v1/rooms/{code}/host)
	MakeRoomHost(w http.ResponseWriter, r *http.Request, code RoomCode)
	// KickRoomPlayer The host sends a player away; they cannot come back to this room.
	// (POST /v1/rooms/{code}/kick)
	KickRoomPlayer(w http.ResponseWriter, r *http.Request, code RoomCode)
	// LeaveRoom The caller leaves the room. During a game their scores stay in its table.
	// (POST /v1/rooms/{code}/leave)
	LeaveRoom(w http.ResponseWriter, r *http.Request, code RoomCode)
	// RoomLive The room, live: a WebSocket that joins it and gets its state after every change.
	// (GET /v1/rooms/{code}/live)
	RoomLive(w http.ResponseWriter, r *http.Request, code RoomCode)
	// NextRoomRound The host goes on from a round's result, to the next round or the game's table.
	// (POST /v1/rooms/{code}/next)
	NextRoomRound(w http.ResponseWriter, r *http.Request, code RoomCode)
	// RoomRoundFailed The caller's viewer could not open the panorama; before anyone has, everyone gets another.
	// (POST /v1/rooms/{code}/rounds/{n}/fail)
	RoomRoundFailed(w http.ResponseWriter, r *http.Request, code RoomCode, n RoundN)
	// RoomGuess The caller's answer (or none). Sent twice, or after the round ended, it changes nothing.
	// (POST /v1/rooms/{code}/rounds/{n}/guess)
	RoomGuess(w http.ResponseWriter, r *http.Request, code RoomCode, n RoundN)
	// RoomHint Spends one of the caller's hints; it is the last of `round.hints`.
	// (POST /v1/rooms/{code}/rounds/{n}/hint)
	RoomHint(w http.ResponseWriter, r *http.Request, code RoomCode, n RoundN)
	// RoomPin The caller moved their pin without guessing yet; it counts if the round ends first.
	// (POST /v1/rooms/{code}/rounds/{n}/pin)
	RoomPin(w http.ResponseWriter, r *http.Request, code RoomCode, n RoundN)
	// RoomRoundShown The caller's viewer opened the round's panorama. The first one starts the clock.
	// (POST /v1/rooms/{code}/rounds/{n}/shown)
	RoomRoundShown(w http.ResponseWriter, r *http.Request, code RoomCode, n RoundN)
	// SetRoomRules The host changes the map or the rules, between games (back to the lobby).
	// (POST /v1/rooms/{code}/rules)
	SetRoomRules(w http.ResponseWriter, r *http.Request, code RoomCode)
	// StartRoomGame The host starts a game, from the lobby or after one (a rematch).
	// (POST /v1/rooms/{code}/start)
	StartRoomGame(w http.ResponseWriter, r *http.Request, code RoomCode)
	// StartSession Returns the current player, creating a guest on the first visit.
	// (POST /v1/session)
	StartSession(w http.ResponseWriter, r *http.Request)
	// GetProfile A player's public profile.
	// (GET /v1/users/{userId})
	GetProfile(w http.ResponseWriter, r *http.Request, userId UserId)
	// ReportUser Reports a player to the admins (a rude name, cheating, other).
	// (POST /v1/users/{userId}/report)
	ReportUser(w http.ResponseWriter, r *http.Request, userId UserId)
}

